css:
@import url("https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700&family=Poppins:wght@500;600;700;800&display=swap");
@import url("https://fonts.googleapis.com/css2?family=Plus+Jakarta+Sans:wght@500;600;700;800&family=Inter:wght@400;500;600;700&display=swap");

ul,ol{list-style:revert;margin:revert;padding:revert}
li{list-style:revert}
img,svg,video{max-width:revert;height:revert;display:revert;vertical-align:revert}
button,input,select,textarea{font:revert;color:revert;background:revert;border:revert;margin:revert;padding:revert;text-align:revert;line-height:revert}
table{border-collapse:revert;text-indent:revert}
blockquote,figure,fieldset{margin:revert;padding:revert}
h1,h2,h3,h4,h5,h6{font-size:revert;font-weight:revert;margin:revert;line-height:revert}
p{margin:revert}
a{color:revert;text-decoration:revert}
hr{border:revert;height:revert;color:revert}

.nifty-part-header-4 {
  --navy:#002c34; --navy-2:#053c46; --navy-3:#00212a;
  --teal:#017994; --teal-2:#0a94b0; --teal-050:#e6f1f4; --teal-100:#cfe6ec;
  --gold:#f0b429; --gold-2:#f7c74c; --gold-d:#cf9410;
  --ink:#0f2a31; --body:#4c5c63; --muted:#88979e;
  --mist:#eef4f6; --mist-2:#f6fafb; --line:#dde8ea; --line-2:#e9f0f2; --line-ink:rgba(255,255,255,.14);
  --white:#fff;
  --max:1240px; --gut:40px;
  --disp:"Plus Jakarta Sans",-apple-system,BlinkMacSystemFont,"Segoe UI",Roboto,sans-serif;
  --f:"Inter",-apple-system,BlinkMacSystemFont,"Segoe UI",Roboto,Helvetica,Arial,sans-serif;
  --shadow:0 12px 34px rgba(0,44,52,.10); --shadow-lg:0 30px 70px rgba(0,44,52,.16);
}
.nifty-part-header-4 * {box-sizing:border-box}
.nifty-part-header-4 {scroll-behavior:smooth}
.nifty-part-header-4 {margin:0;font-family:var(--f);color:var(--body);background:var(--white);line-height:1.7;-webkit-font-smoothing:antialiased;overflow-x:clip}
.nifty-part-header-4 a {text-decoration:none;color:inherit}
.nifty-part-header-4 img {max-width:100%;display:block}
.nifty-part-header-4 h1, .nifty-part-header-4 h2, .nifty-part-header-4 h3, .nifty-part-header-4 h4 {margin:0;color:var(--ink);font-family:var(--disp);font-weight:700;line-height:1.1;letter-spacing:-.02em}
.nifty-part-header-4 p {margin:0}
.nifty-part-header-4 .wrap {max-width:var(--max);margin:0 auto;padding:0 var(--gut)}
@media(max-width:768px) {.nifty-part-header-4 {--gut:26px}}
@media(max-width:430px) {.nifty-part-header-4 {--gut:20px}}
.nifty-part-header-4 .ic {width:1em;height:1em;flex:none;stroke:currentColor;fill:none;stroke-width:1.8;stroke-linecap:round;stroke-linejoin:round}
.nifty-part-header-4 .eyebrow {display:inline-flex;align-items:center;gap:10px;font-size:.76rem;font-weight:700;letter-spacing:.16em;text-transform:uppercase;color:var(--teal)}
.nifty-part-header-4 .eyebrow.on-dark {color:var(--gold-2)}
.nifty-part-header-4 .btn {display:inline-flex;align-items:center;justify-content:center;gap:10px;font-family:var(--f);font-weight:700;font-size:.92rem;letter-spacing:.01em;padding:15px 28px;border-radius:40px;cursor:pointer;border:2px solid transparent;transition:.2s;white-space:nowrap}
.nifty-part-header-4 .btn .ic {width:17px;height:17px;stroke-width:2.4}
.nifty-part-header-4 .btn-gold {background:var(--gold);color:var(--navy);box-shadow:0 10px 24px rgba(240,180,41,.36)}
.nifty-part-header-4 .btn-gold:hover {background:var(--gold-2);transform:translateY(-2px)}
.nifty-part-header-4 .btn-navy {background:var(--navy);color:#fff}
.nifty-part-header-4 .btn-navy:hover {background:var(--navy-2);transform:translateY(-2px)}
.nifty-part-header-4 .btn-teal {background:var(--teal);color:#fff}
.nifty-part-header-4 .btn-teal:hover {background:var(--teal-2);transform:translateY(-2px)}
.nifty-part-header-4 .btn-ghost {background:transparent;color:var(--navy);border-color:var(--line)}
.nifty-part-header-4 .btn-ghost:hover {border-color:var(--navy);transform:translateY(-2px)}
.nifty-part-header-4 .btn-ghost-lt {background:rgba(255,255,255,.06);color:#fff;border-color:rgba(255,255,255,.4)}
.nifty-part-header-4 .btn-ghost-lt:hover {background:#fff;color:var(--navy);border-color:#fff}
.nifty-part-header-4 .section {padding:96px 0;position:relative}
.nifty-part-header-4 .sec-head {max-width:720px;margin:0 auto 54px;text-align:center}
.nifty-part-header-4 .sec-head h2 {font-size:clamp(1.9rem,3.6vw,2.7rem)}
.nifty-part-header-4 .sec-head h2 em {font-style:normal;color:var(--teal)}
.nifty-part-header-4 .sec-head p {margin-top:15px;font-size:1.06rem;color:var(--body)}
.nifty-part-header-4 .tag {display:inline-block;background:var(--teal-050);color:var(--teal);border:1px solid var(--teal-100);border-radius:20px;font-size:.72rem;font-weight:700;letter-spacing:.06em;text-transform:uppercase;padding:5px 12px}
.nifty-part-header-4 .ph {background:var(--mist);display:block;width:100%;height:100%;object-fit:cover}
.nifty-part-header-4 .rv {animation:rvIn .7s cubic-bezier(.2,.7,.2,1) both}
.nifty-part-header-4 .rv.d1 {animation-delay:.08s}
.nifty-part-header-4 .rv.d2 {animation-delay:.16s}
.nifty-part-header-4 .rv.d3 {animation-delay:.24s}
.nifty-part-header-4 .rv.d4 {animation-delay:.32s}
@keyframes rvIn {from{opacity:0;transform:translateY(26px)}to{opacity:1;transform:none}}
@media(prefers-reduced-motion:reduce) {.nifty-part-header-4 .rv {animation:none}}
.nifty-part-header-4 .util {background:var(--navy);color:#c7d6da;font-size:.82rem}
.nifty-part-header-4 .util .wrap {display:flex;align-items:center;justify-content:space-between;gap:16px;min-height:44px}
.nifty-part-header-4 .util .u-l {display:flex;gap:24px;align-items:center}
.nifty-part-header-4 .util .u-l a, .nifty-part-header-4 .util .u-l span {display:inline-flex;align-items:center;gap:8px}
.nifty-part-header-4 .util a:hover {color:#fff}
.nifty-part-header-4 .util .ic {width:15px;height:15px;color:var(--gold-2)}
.nifty-part-header-4 .util strong {color:#fff;font-weight:700}
.nifty-part-header-4 .util .u-r {display:flex;gap:20px;align-items:center}
.nifty-part-header-4 .util .cred {display:inline-flex;align-items:center;gap:8px;color:#9fb6bc}
@media(max-width:900px) {.nifty-part-header-4 .util .u-r {display:none}}
@media(max-width:560px) {.nifty-part-header-4 .util .u-l {gap:14px}
.nifty-part-header-4 .util .u-l .hide-xs {display:none}}
.nifty-part-header-4 .hdr {position:sticky;top:0;z-index:70;background:rgba(255,255,255,.96);backdrop-filter:blur(10px);border-bottom:1px solid var(--line)}
.nifty-part-header-4 .hdr-in {display:flex;align-items:center;gap:16px;min-height:82px}
.nifty-part-header-4 .brand {flex:none;display:flex;align-items:center}
.nifty-part-header-4 .brand img {height:52px;width:auto;display:block}
.nifty-part-header-4 .nav-cb {display:none}
.nifty-part-header-4 .nav {margin-left:auto;display:flex;align-items:center;gap:20px}
.nifty-part-header-4 .nav-links {display:flex;align-items:center;gap:1px;list-style:none;margin:0;padding:0}
.nifty-part-header-4 .nav-links>li>a {display:flex;align-items:center;gap:5px;padding:9px 9px;font-family:var(--f);font-size:.82rem;font-weight:600;color:var(--ink);border-radius:8px;letter-spacing:0;white-space:nowrap}
.nifty-part-header-4 .nav-links>li>a:hover {color:var(--teal);background:var(--teal-050)}
.nifty-part-header-4 .nav-links>li.active>a {color:var(--teal)}
.nifty-part-header-4 .nav-links .caret {width:13px;height:13px;stroke-width:2.4}
.nifty-part-header-4 .has-drop {position:relative}
.nifty-part-header-4 .has-drop .drop-cb {display:none}
.nifty-part-header-4 .dropdown {position:absolute;top:calc(100% + 6px);left:0;min-width:250px;background:#fff;border:1px solid var(--line);border-radius:14px;box-shadow:var(--shadow-lg);padding:8px;opacity:0;visibility:hidden;transition:.15s;z-index:80}
.nifty-part-header-4 .has-drop:hover .dropdown {opacity:1;visibility:visible;top:calc(100% + 2px)}
.nifty-part-header-4 .dropdown a {display:flex;align-items:center;gap:10px;padding:11px 13px;border-radius:9px;font-family:var(--f);font-size:.86rem;font-weight:600;color:var(--ink)}
.nifty-part-header-4 .dropdown a:hover {background:var(--teal-050);color:var(--teal)}
.nifty-part-header-4 .dropdown a .dot {width:7px;height:7px;border-radius:50%;background:var(--gold);flex:none}
.nifty-part-header-4 .hdr-cta {display:flex;align-items:center;gap:13px;flex:none}
.nifty-part-header-4 .hdr-phone {display:inline-flex;flex-direction:column;line-height:1.1;text-align:right}
.nifty-part-header-4 .hdr-phone small {font-size:.64rem;letter-spacing:.1em;text-transform:uppercase;color:var(--muted);font-weight:700}
.nifty-part-header-4 .hdr-phone b {font-size:1.02rem;color:var(--navy);font-family:var(--disp);font-weight:800}
.nifty-part-header-4 .burger {display:none;margin-left:auto;width:48px;height:48px;border:1px solid var(--line);border-radius:11px;cursor:pointer;align-items:center;justify-content:center;color:var(--navy);background:#fff}
.nifty-part-header-4 .burger svg {width:24px;height:24px;stroke-width:2}
.nifty-part-header-4 .burger .x {display:none}
.nifty-part-header-4 .nav-cb:checked ~ .burger .menu {display:none}
.nifty-part-header-4 .nav-cb:checked ~ .burger .x {display:block}
@media(max-width:1360px) {.nifty-part-header-4 .burger {display:flex}
.nifty-part-header-4 .nav {position:fixed;inset:0 0 0 auto;top:0;height:100vh;width:min(360px,88vw);margin:0;background:#fff;flex-direction:column;align-items:stretch;gap:0;padding:26px 0 30px;box-shadow:var(--shadow-lg);clip-path:inset(0 0 0 100%);pointer-events:none;transition:clip-path .32s ease;overflow-y:auto;z-index:90}
.nifty-part-header-4 .nav-cb:checked ~ .nav {clip-path:inset(0 0 0 0);pointer-events:auto}
.nifty-part-header-4 .nav-links {flex-direction:column;align-items:stretch;gap:0;width:100%}
.nifty-part-header-4 .nav-links>li>a {justify-content:space-between;padding:16px 26px;border-bottom:1px solid var(--line-2);border-radius:0;font-size:.98rem}
.nifty-part-header-4 .nav-links>li.has-drop>a {display:none}
.nifty-part-header-4 .dropdown {position:static;opacity:1;visibility:visible;box-shadow:none;border:0;border-radius:0;min-width:0;padding:0;max-height:0;overflow:hidden;transition:max-height .3s ease;background:var(--mist-2)}
.nifty-part-header-4 .drop-cb:checked ~ .dropdown {max-height:420px}
.nifty-part-header-4 .drop-lbl {display:flex!important;align-items:center;justify-content:space-between;padding:16px 26px;border-bottom:1px solid var(--line-2);font-family:var(--f);font-weight:600;font-size:.98rem;color:var(--ink);cursor:pointer}
.nifty-part-header-4 .drop-cb:checked ~ .drop-lbl .caret {transform:rotate(180deg)}
.nifty-part-header-4 .drop-lbl .caret {transition:.25s;width:15px;height:15px}
.nifty-part-header-4 .dropdown a {padding:14px 34px}
.nifty-part-header-4 .hdr-cta {display:none}
.nifty-part-header-4 .nav .m-cta {display:flex;flex-direction:column;gap:12px;padding:22px 26px 0}
.nifty-part-header-4 .nav .m-cta .btn {width:100%}}
@media(min-width:1361px) {.nifty-part-header-4 .drop-lbl {display:none}
.nifty-part-header-4 .nav .m-cta {display:none}}
.nifty-part-header-4 .scrim {display:none}
@media(max-width:1360px) {.nifty-part-header-4 .nav-cb:checked ~ .scrim {display:block;position:fixed;inset:0;background:rgba(0,20,26,.5);z-index:85}}
.nifty-part-header-4 .hero {position:relative;overflow:hidden;background:radial-gradient(1100px 620px at 88% -6%,var(--teal-050),transparent 62%),linear-gradient(180deg,var(--mist-2),var(--white) 70%)}
.nifty-part-header-4 .hero::before {content:"";position:absolute;top:-140px;right:-120px;width:520px;height:520px;border-radius:50%;background:radial-gradient(circle,rgba(1,121,148,.10),transparent 68%);pointer-events:none}
.nifty-part-header-4 .hero-grid {position:relative;z-index:2;display:grid;grid-template-columns:1.08fr .92fr;gap:56px;align-items:center;padding-top:70px;padding-bottom:84px}
.nifty-part-header-4 .hero-pill {display:inline-flex;align-items:center;gap:10px;background:#fff;border:1px solid var(--line);border-radius:40px;padding:8px 16px 8px 8px;font-size:.8rem;font-weight:600;color:var(--ink);box-shadow:var(--shadow)}
.nifty-part-header-4 .hero-pill .p-ic {width:26px;height:26px;border-radius:50%;background:var(--teal);color:#fff;display:grid;place-items:center;flex:none}
.nifty-part-header-4 .hero-pill .p-ic .ic {width:15px;height:15px;stroke-width:2.6}
.nifty-part-header-4 .hero-pill b {color:var(--teal);font-weight:700}
.nifty-part-header-4 .hero h1 {margin-top:22px;font-size:clamp(2.5rem,5.4vw,4.2rem);line-height:1.02;font-weight:800;color:var(--navy);letter-spacing:-.03em}
.nifty-part-header-4 .hero h1 em {font-style:normal;color:var(--teal);position:relative;white-space:nowrap}
.nifty-part-header-4 .hero h1 em::after {content:"";position:absolute;left:0;right:0;bottom:.06em;height:.14em;background:var(--gold);opacity:.5;border-radius:3px;z-index:-1}
.nifty-part-header-4 .hero .lead {margin-top:22px;font-size:1.14rem;color:var(--body);max-width:42ch}
.nifty-part-header-4 .hero-chips {display:flex;flex-wrap:wrap;gap:9px;margin-top:24px}
.nifty-part-header-4 .hero-chips span {background:#fff;border:1px solid var(--line);border-radius:30px;padding:8px 15px;font-size:.82rem;font-weight:600;color:var(--navy)}
.nifty-part-header-4 .hero-chips span b {color:var(--teal)}
.nifty-part-header-4 .hero-cta {display:flex;flex-wrap:wrap;gap:14px;margin-top:30px}
.nifty-part-header-4 .hero-trust {display:flex;flex-wrap:wrap;gap:10px 22px;margin-top:28px}
.nifty-part-header-4 .hero-trust span {display:inline-flex;align-items:center;gap:8px;font-size:.9rem;font-weight:600;color:var(--navy)}
.nifty-part-header-4 .hero-trust .ic {width:20px;height:20px;color:#fff;background:var(--teal);border-radius:50%;padding:4px;stroke-width:3}
.nifty-part-header-4 .hero-visual {position:relative}
.nifty-part-header-4 .hv-photo {border-radius:22px;overflow:hidden;aspect-ratio:4/5;box-shadow:var(--shadow-lg);position:relative}
.nifty-part-header-4 .hv-photo::after {content:"";position:absolute;inset:0;background:linear-gradient(180deg,transparent 55%,rgba(0,44,52,.18))}
.nifty-part-header-4 .hv-card {position:absolute;background:#fff;border-radius:16px;box-shadow:var(--shadow-lg);padding:16px 18px}
.nifty-part-header-4 .hv-card.dash {left:-30px;top:40px;width:230px}
.nifty-part-header-4 .hv-card.dash .dh {display:flex;align-items:center;justify-content:space-between;margin-bottom:12px}
.nifty-part-header-4 .hv-card.dash .dh small {font-size:.66rem;letter-spacing:.1em;text-transform:uppercase;color:var(--muted);font-weight:700}
.nifty-part-header-4 .hv-card.dash .dh .dot {width:9px;height:9px;border-radius:50%;background:var(--teal)}
.nifty-part-header-4 .hv-card.dash .amt {font-family:var(--disp);font-weight:800;font-size:1.5rem;color:var(--navy)}
.nifty-part-header-4 .hv-card.dash .amt span {color:var(--teal)}
.nifty-part-header-4 .hv-card.dash .sub {font-size:.72rem;color:var(--muted);margin-top:2px}
.nifty-part-header-4 .hv-card.dash .bars {display:flex;align-items:flex-end;gap:6px;height:46px;margin-top:12px}
.nifty-part-header-4 .hv-card.dash .bars i {flex:1;background:var(--teal-100);border-radius:3px 3px 0 0}
.nifty-part-header-4 .hv-card.dash .bars i.on {background:var(--teal)}
.nifty-part-header-4 .hv-card.badge {right:-24px;bottom:60px;display:flex;align-items:center;gap:12px;width:auto}
.nifty-part-header-4 .hv-card.badge .b-ic {width:42px;height:42px;border-radius:11px;background:var(--gold);color:var(--navy);display:grid;place-items:center;flex:none}
.nifty-part-header-4 .hv-card.badge b {display:block;font-family:var(--disp);font-weight:800;color:var(--navy);font-size:.98rem;line-height:1.1}
.nifty-part-header-4 .hv-card.badge small {font-size:.72rem;color:var(--muted)}
.nifty-part-header-4 .hv-chat {position:absolute;right:-10px;top:-18px;background:var(--navy);color:#dbe9ec;font-size:.78rem;padding:12px 15px;border-radius:14px 14px 14px 3px;max-width:210px;box-shadow:var(--shadow-lg);z-index:3}
.nifty-part-header-4 .hv-chat b {color:#fff}
@media(max-width:960px) {.nifty-part-header-4 .hero-grid {grid-template-columns:1fr;gap:44px;padding-top:44px;padding-bottom:60px}
.nifty-part-header-4 .hero .lead {max-width:none}
.nifty-part-header-4 .hv-card.dash {left:0}
.nifty-part-header-4 .hv-card.badge {right:0}
.nifty-part-header-4 .hv-chat {display:none}}
@media(max-width:520px) {.nifty-part-header-4 .hv-card.dash {width:190px}
.nifty-part-header-4 .hv-chat {display:none}}
.nifty-part-header-4 .accred {background:#fff;border-bottom:1px solid var(--line)}
.nifty-part-header-4 .accred .wrap {padding:30px 24px}
.nifty-part-header-4 .accred .lbl {text-align:center;font-size:.74rem;font-weight:700;letter-spacing:.14em;text-transform:uppercase;color:var(--muted);margin-bottom:20px}
.nifty-part-header-4 .accred .row {display:flex;flex-wrap:wrap;align-items:center;justify-content:center;gap:16px 34px}
.nifty-part-header-4 .accred .a {display:inline-flex;align-items:center;gap:9px;font-family:var(--disp);font-weight:700;color:#5c6d74;font-size:1rem;letter-spacing:.01em}
.nifty-part-header-4 .accred .a .ic {width:20px;height:20px;color:var(--teal)}
.nifty-part-header-4 .accred .a small {display:block;font-family:var(--f);font-weight:600;font-size:.62rem;color:var(--muted);letter-spacing:.04em}
.nifty-part-header-4 .accred .a-img {display:inline-flex;align-items:center}
.nifty-part-header-4 .accred .a-img img {height:42px;width:auto;display:block}
.nifty-part-header-4 .accred .row {gap:18px 30px}
@media(max-width:560px) {.nifty-part-header-4 .accred .a-img img {height:34px}}
.nifty-part-header-4 .pillars {background:var(--mist)}
.nifty-part-header-4 .pillar-grid {display:grid;grid-template-columns:repeat(3,1fr);gap:26px}
.nifty-part-header-4 .pillar {background:#fff;border:1px solid var(--line);border-radius:20px;padding:34px 30px 30px;transition:.24s;position:relative;overflow:hidden}
.nifty-part-header-4 .pillar::before {content:"";position:absolute;top:0;left:0;right:0;height:4px;background:linear-gradient(90deg,var(--teal),var(--teal-2));transform:scaleX(0);transform-origin:left;transition:.3s}
.nifty-part-header-4 .pillar:hover {transform:translateY(-8px);box-shadow:var(--shadow-lg);border-color:transparent}
.nifty-part-header-4 .pillar:hover::before {transform:scaleX(1)}
.nifty-part-header-4 .pillar .pi {width:62px;height:62px;border-radius:16px;background:var(--teal-050);color:var(--teal);display:grid;place-items:center;margin-bottom:20px}
.nifty-part-header-4 .pillar .pi .ic {width:30px;height:30px}
.nifty-part-header-4 .pillar h3 {font-size:1.32rem;letter-spacing:-.01em}
.nifty-part-header-4 .pillar p {margin-top:12px;font-size:.97rem;color:var(--body)}
.nifty-part-header-4 .pillar .more {display:inline-flex;align-items:center;gap:8px;margin-top:20px;font-weight:700;font-size:.86rem;color:var(--teal)}
.nifty-part-header-4 .pillar:hover .more .ic {transform:translateX(4px)}
.nifty-part-header-4 .pillar .more .ic {width:16px;height:16px;stroke-width:2.6;transition:.2s}
@media(max-width:900px) {.nifty-part-header-4 .pillar-grid {grid-template-columns:1fr}}
.nifty-part-header-4 .about-grid {display:grid;grid-template-columns:.95fr 1.05fr;gap:66px;align-items:center}
